def bulk_price(unit_price, qty, coupon):
    """คืนยอดชำระเป็นสตางค์ (จำนวนเต็ม) คำนวณด้วยจำนวนเต็มล้วน ปัดเศษครั้งเดียวตอนท้าย (half up)"""
    num = unit_price * qty
    den = 1
    if qty >= 50:
        num *= 925; den *= 1000      # ลด 7.5%
    elif qty >= 10:
        num *= 965; den *= 1000      # ลด 3.5%
    if coupon:
        num *= 9
